import{_ as t,o as a,c as r,a2 as n}from"./chunks/framework.yJK3qstQ.js";const u=JSON.parse('{"title":"Project Pitch: Gesture PDF Presenter","description":"","frontmatter":{},"headers":[],"relativePath":"00b-project-pitch.md","filePath":"00b-project-pitch.md"}'),i={name:"00b-project-pitch.md"};function o(s,e,c,l,d,p){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="project-pitch-gesture-pdf-presenter" tabindex="-1">Project Pitch: Gesture PDF Presenter <a class="header-anchor" href="#project-pitch-gesture-pdf-presenter" aria-label="Permalink to &quot;Project Pitch: Gesture PDF Presenter&quot;">​</a></h1><h2 id="_30-second-elevator-pitch" tabindex="-1">30-Second Elevator Pitch <a class="header-anchor" href="#_30-second-elevator-pitch" aria-label="Permalink to &quot;30-Second Elevator Pitch&quot;">​</a></h2><p>&quot;I built the <strong>Gesture PDF Presenter</strong>, an interactive touchless presentation system powered by MediaPipe computer vision, React 18, and PDF.js. Using a standard laptop webcam, it tracks 21 hand landmarks in real time to let speakers advance slides, zoom into diagrams, and activate a virtual laser pointer using natural hand gestures in mid-air—eliminating the need for handheld clickers or touching a keyboard.&quot;</p><h2 id="_2-minute-spoken-pitch" tabindex="-1">2-Minute Spoken Pitch <a class="header-anchor" href="#_2-minute-spoken-pitch" aria-label="Permalink to &quot;2-Minute Spoken Pitch&quot;">​</a></h2><p>&quot;Every presenter has experienced the awkward dance of holding a physical clicker, accidentally pressing the wrong button, or being tethered to a podium keyboard while trying to engage an audience.</p><p>To create a natural presentation experience, I engineered the Gesture PDF Presenter:</p><p>First, for real-time vision without cloud latency, our application runs Google&#39;s MediaPipe Hands model entirely client-side using WebAssembly and WebGL. It tracks 21 distinct 3D knuckle and fingertip landmarks from a standard webcam stream at 30 frames per second.</p><p>Second, in <code>GestureControl.tsx</code>, I built a geometric gesture recognition engine. Rather than relying on black-box neural networks that are prone to lag, it computes Euclidean vectors and angle differentials between fingertip landmarks. For instance, detecting an extended index finger while the other three fingers remain curled activates our virtual laser pointer overlay.</p><p>Third, to prevent accidental slide flips when a speaker naturally gestures while talking, I implemented a temporal debounce filter with directional velocity thresholds. A slide transition only triggers if an open palm moves laterally across the frame at over 400 pixels per second and stays stable for at least 300 milliseconds.</p><p>Finally, on the document layer, we use PDF.js and HTML5 Canvas to render vectorized PDF slides with crisp scaling, allowing presenters to draw live digital annotations and zoom into charts using two-finger pinch gestures.</p><p>The entire system requires zero dedicated hardware—just a browser and a webcam.&quot;</p>',11)])])}const m=t(i,[["render",o]]);export{u as __pageData,m as default};
